// Scoped enum with default underlying type (int)
enum class DefaultStatus { ok, error };

// Scoped enum with explicitly specified underlying type
enum class Status : std::uint32_t {
    good = 0,
    failed = 1,
    corrupt = 200
};

// Unscoped enum with a specified underlying type (can now be forward-declared)
enum Color : std::uint8_t { red, green, blue };
